"""Editorial revisions for consumer psychology and advertising."""

from review_angle_plans import audit, revise_domain


CONSUMER = """history_origins|The Birth of a Buyer Assumption|When did one idea about consumer choice enter market research?|Trace original study, setting, measures, and later uses.
famous_examples|A Famous Choice Experiment Revisited|Does a celebrated consumer experiment replicate in another setting?|Compare original and independent designs, samples, and outcomes.
hidden_stories|Who Is Missing From the Shopper Model?|Which consumers are excluded from one market-research sample?|Check income, disability, language, geography, and recruitment method.
beginner_explainers|How a Choice Is Framed|How can the same offer appear different under two presentations?|Compare matched price, terms, and wording with a defined consumer group.
advanced_concepts|Preference Versus Constraint|When does a purchase reflect available options more than preference?|Compare budget, location, timing, and measured alternatives.
mysteries_unsolved_cases|Why Did Shoppers Switch?|Which factors could explain a change in purchases?|Test price, availability, promotion, season, and substitution before attribution.
technology_innovation|Recommendations and Decisions|How does one recommendation system change which products people see?|Inspect ranking signals, exposure, defaults, and consumer outcomes.
people_personalities|The Researcher Behind a Finding|How did one researcher define and measure a consumer behavior?|Read methods and collaborators rather than popularized anecdotes.
major_events|A Shock Changes Buying|How did one dated disruption alter purchase patterns?|Compare transactions, supply, income, and timing for a defined market.
how_it_works|From Need to Purchase|Which steps and constraints shape one buying decision?|Map search, comparison, terms, checkout, and postpurchase experience.
rise_fall|A Consumer Trend Fades|Did one product trend disappear or shift channels?|Compare sales, survey measures, demographics, and replacement products.
then_vs_now|Buying the Same Product Across Time|How did choice, price, credit, and information change?|Use comparable products and inflation-adjusted measures.
future_developments|A New Choice Interface|What would show whether a proposed interface helps consumers decide?|Predefine comprehension, price, privacy, and cancellation measures.
myths_vs_facts|The Irrational Shopper Label|Does one observed behavior imply irrationality?|Check information, constraints, incentives, and alternative explanations.
documentary_stories|An Offer From Ad to Return|How did one offer move through attention, purchase, use, and refund?|Trace claims and actual consumer experience in a bounded case.
value_chain|Who Shapes the Choice Environment?|Which sellers, platforms, and intermediaries influence a buyer's options?|Map ranking, inventory, payments, and incentives for one product.
incentive_map|Why This Option Is Prominent|Who benefits when one offer is highlighted or preselected?|Compare placement fees, commissions, defaults, and consumer knowledge.
unit_economics|The Cost of a Consumer Offer|Does a heavily discounted offer recover cost through later purchases?|Use disclosed figures or labeled scenarios; avoid asserting hidden profits.
consumer_outcome|Did the Buyer Benefit?|What happened after consumers selected one promoted option?|Compare use, complaints, refunds, and satisfaction against a defined alternative.
market_structure|How Many Choices Are Real?|Do apparently competing listings come from independent sellers?|Trace ownership, fulfillment, and price coordination evidence.
risk_transfer|The Risk in the Fine Print|Which terms shift cost or uncertainty onto a consumer?|Compare warranties, subscriptions, cancellation, and actual claims.
regulatory_choice|A Rule Against Manipulative Design|Did one disclosure or design rule improve informed choice?|Compare implementation, comprehension, and enforcement in a jurisdiction.
historical_shock|Choices During Scarcity|How did a supply shock change what consumers could buy?|Separate preference from stockouts, rationing, and price changes.
data_definition|What Does Conversion Mean?|Does a reported conversion metric count meaningful purchases?|Check denominator, returns, repeat orders, and time window.
access_and_affordability|Who Can Reach the Offer?|Which consumers face higher effective prices or fewer options?|Compare delivery, credit, language, disability access, and time cost.
business_failure|When the Loyalty Strategy Failed|Why did one company misread its customers?|Compare predicted behavior, actual sales, churn, and alternative causes.
long_term_tradeoff|A Cheap Offer's Later Cost|Do upfront savings hide maintenance, data, or subscription costs?|Use a defined time horizon and actual contract terms.
field_supply_chain|Choice Starts Before the Shelf|Which supply limits shape the options shoppers see?|Trace availability, allocation, and retailer decisions for one product.
field_brand_claims|Testing a Promise|Does one brand claim match measurable consumer outcomes?|Identify implied claim, substantiation, comparator, and date.
field_customer_experience|The Checkout Friction Test|Where do consumers misunderstand one purchase flow?|Observe consented user sessions and measure errors, reversals, and comprehension.
field_market_entry|A New Brand and Consumer Trust|How did a new entrant earn or fail to earn repeat buyers?|Compare claims, trial, satisfaction, price, and distribution.
field_product_lifecycle|The Decision After Purchase|How do repair, replacement, and disposal affect consumer value?|Compare actual lifespan, warranty use, repair access, and total cost."""


MARKETING = """history_origins|Where a Campaign Method Came From|How did one advertising method emerge and spread?|Trace early examples, audience data, and changes in media.
famous_examples|A Famous Campaign Under Review|Which measured effects can be linked to a celebrated campaign?|Compare sales, reach, baseline trends, and concurrent price or distribution changes.
hidden_stories|The Labor Behind an Ad|Who researched, made, placed, and moderated one campaign?|Credit creative, technical, and contract workers through production records.
beginner_explainers|What an Ad Actually Claims|How can viewers identify explicit and implied claims in one advertisement?|Compare wording, imagery, disclosures, and likely audience interpretation.
advanced_concepts|Causality in Campaign Measurement|Does an attribution model show incremental sales?|Compare holdout evidence, selection bias, and attribution windows.
mysteries_unsolved_cases|Why Did a Campaign Fail?|Which explanations fit a campaign's disappointing result?|Examine creative, reach, targeting, price, stock, and competing messages.
technology_innovation|Targeting Changes the Audience|How does one targeting tool select who sees an ad?|Inspect inputs, exclusions, privacy controls, and observed distribution.
people_personalities|Who Approved the Message?|How did named contributors shape one campaign claim?|Trace briefs, review, revisions, and accountability without hero stories.
major_events|An Ad After a Public Controversy|How did a company revise messaging after a dated challenge?|Compare claims, evidence, audience response, and actual product changes.
how_it_works|From Brief to Published Ad|Which steps turn a marketing goal into a consumer-facing message?|Follow research, creative, substantiation, approvals, placement, and measurement.
rise_fall|A Channel Loses Effectiveness|Why did one advertising channel's measured return change?|Compare costs, audience behavior, measurement rules, and competition.
then_vs_now|The Same Product, Two Eras of Ads|How did claims, disclosure, and audience targeting change?|Compare dated campaigns under their respective legal contexts.
future_developments|Evaluating a New Campaign Tool|What evidence would justify using a proposed automated ad tool?|Define accuracy, bias, privacy, cost, and human review conditions.
myths_vs_facts|The Viral Ad Story Checked|Did a campaign truly spread without paid placement?|Trace media buys, partnerships, shares, and measurement limits.
documentary_stories|One Claim's Approval Trail|How did a product claim survive or fail substantiation review?|Build a dated record of evidence, legal review, publication, and correction.
value_chain|Money Behind the Ad|How do agency, platform, publisher, and creator share campaign revenue?|Map contracts, fees, and reporting for a bounded campaign.
incentive_map|Why This Metric Was Chosen|Who benefits when a campaign optimizes clicks instead of outcomes?|Compare agency, platform, and advertiser incentives with consumer effects.
unit_economics|A Campaign's Real Cost|How do creative, media, data, and fees affect cost per incremental sale?|Use disclosed numbers or labeled examples, including uncertainty.
consumer_outcome|What Did the Audience Understand?|Did viewers understand a material condition in one advertisement?|Use comprehension tests with the actual ad and audience.
market_structure|A Concentrated Ad Market|How does one platform's position affect advertiser choice?|Compare reach, switching costs, fees, and measurement access.
risk_transfer|Who Bears a False Claim?|How are costs of a misleading ad distributed among buyers and sellers?|Trace complaints, refunds, enforcement, and contract obligations.
regulatory_choice|A Disclosure Rule in Practice|Did a required disclosure become visible and understandable?|Compare local rule, actual placement, user comprehension, and enforcement.
historical_shock|Advertising During a Supply Crisis|What changed when a campaign ran amid shortage or disruption?|Separate message effects from inventory and price changes.
data_definition|What Is Reach?|Do reported impressions represent distinct people or meaningful exposure?|Check deduplication, bots, frequency, and measurement period.
access_and_affordability|Who Sees the Offer?|Which audiences are excluded by targeting, language, or channel choice?|Compare delivery data and accessible versions with intended audience.
business_failure|A Campaign That Hurt Trust|Which evidence links one campaign to complaints or brand decline?|Compare timing, alternative events, surveys, and actual customer behavior.
long_term_tradeoff|Short Sales Versus Lasting Trust|Did one urgency tactic increase immediate sales but raise later complaints?|Compare cohorts, cancellation, returns, and customer retention.
field_supply_chain|When the Ad Outruns Stock|Did a campaign promise availability the supply chain could not deliver?|Compare demand forecast, inventory, delivery, and customer remedies.
field_brand_claims|Substantiating a Brand Promise|What evidence supports one advertised benefit or superiority claim?|Identify comparator, test conditions, typical result, and local legal standard.
field_customer_experience|From Click to Actual Terms|Does the landing page match the ad's price and conditions?|Trace a documented customer journey including fees and cancellation.
field_market_entry|Launching a Brand Claim|Which claims helped a newcomer gain trial, and were they substantiated?|Compare creative, evidence, distribution, and repeat purchase.
field_product_lifecycle|Advertising After the Sale|Do repair and support experiences match a brand's long-life promise?|Check warranty terms, service data, and consumer reports."""


if __name__ == "__main__":
    revise_domain("105", "105_consumer_psychology", CONSUMER,
                  "Consumer decisions through real choice constraints, interface design, claims, outcomes, and the limits of behavioral inference.",
                  "original behavioral studies, representative consumer research, actual offers and contract terms, transaction data, and current consumer-protection guidance",
                  "Name product, market, consumer group, jurisdiction, and date. Distinguish observed behavior from motives; avoid manipulative shopping advice or universal psychological labels.")
    revise_domain("106", "106_marketing_advertising", MARKETING,
                  "Advertising as a process of creating, substantiating, distributing, measuring, and correcting consumer-facing claims.",
                  "dated campaign materials and contracts, claim-substantiation files where available, audience tests, independent sales measures, and current advertising guidance",
                  "Name campaign, platform, market, jurisdiction, and date. Separate exposure from incremental effect, disclose paid relationships, and verify applicable advertising and privacy rules.")
    rows = audit()
    print(f"Plans: {len(rows)}; reviewed question designs: {sum(r['status'] == 'editorial_question_reviewed' for r in rows)}")
